package game

import (
	"encoding/json"
	"os"
	"strconv"
	"strings"
	"testing"
)

// These vectors are generated by executing gwent.js Row.calcCardScore in Node.
// CI verifies that the golden fixture remains aligned with the JS reference.
func TestScoreParityWithOriginalJavaScript(t *testing.T) {
	type originalUnit struct {
		UID     string `json:"uid"`
		Name    string `json:"name"`
		Power   int    `json:"power"`
		Ability string `json:"ability"`
	}
	type originalCase struct {
		Row         string         `json:"row"`
		Weather     []string       `json:"weather"`
		Bran        bool           `json:"bran"`
		DoubleSpy   bool           `json:"doubleSpy"`
		VirtualHorn bool           `json:"virtualHorn"`
		Units       []originalUnit `json:"units"`
		Expected    []int          `json:"expected"`
	}
	var fixture struct {
		Cases []originalCase `json:"cases"`
	}
	data, err := os.ReadFile("testdata/original-score-goldens.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Cases) < 300 {
		t.Fatalf("expected broad independent JS coverage, got %d cases", len(fixture.Cases))
	}
	for idx, tc := range fixture.Cases {
		c := Catalog{}
		p0 := Player{Rows: rows(), Horn: map[string]bool{tc.Row: tc.VirtualHorn}}
		p1 := Player{Rows: rows()}
		if tc.Bran {
			p0.Leader = len(c) + 1
			c = append(c, Definition{Name: "King Bran", Deck: "skellige", Row: "leader", Ability: "king_bran"})
		}
		if tc.DoubleSpy {
			p1.Leader = len(c) + 1
			c = append(c, Definition{Name: "Eredin", Deck: "monsters", Row: "leader", Ability: "eredin_treacherous"})
		}
		for _, unit := range tc.Units {
			def := len(c)
			c = append(c, Definition{Name: unit.Name, Deck: "realms", Row: tc.Row,
				Strength: strconv.Itoa(unit.Power), Ability: strings.TrimSpace(unit.Ability)})
			p0.Rows[tc.Row] = append(p0.Rows[tc.Row], Card{UID: unit.UID, Def: def})
		}
		if len(tc.Units) != len(tc.Expected) {
			t.Fatalf("case %d: different unit and expected score count", idx)
		}
		r := Room{Players: []Player{p0, p1}, Weather: tc.Weather}
		scores := r.unitPowers(0, tc.Row, c)
		for i, unit := range tc.Units {
			if got, expected := scores[unit.UID], tc.Expected[i]; got != expected {
				t.Fatalf("original JS mismatch at fixture %d, %s (%s): Go=%d JS=%d; weather=%v bran=%v spy=%v horn=%v",
					idx, unit.Name, unit.Ability, got, expected, tc.Weather, tc.Bran, tc.DoubleSpy, tc.VirtualHorn)
			}
		}
	}
}
